	    VM_MAP_PAGE_MASK(ipc_kernel_map)) +
	    VM_MAP_PAGE_SIZE(ipc_kernel_map);
	actual = 0;
}

if (actual == 0) {
	memory = VM_MAP_COPY_NULL;

	kmem_free(ipc_kernel_map, addr, size);
